EXPLAIN SELECT id, UNNEST(arr) FROM items;
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
| plan_type     | plan                                                                                                                                                                                                                             |
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
| logical_plan  | Unnest: arr                                                                                                                                                                                                                      |
|               |   TableScan: items                                                                                                                                                                                                               |
| physical_plan | UnnestExec: list_type=[arr@1], struct_type=[]                                                                                                                                                                                    |
|               |   ProjectionExec: expr=[id@0, arr@1]                                                                                                                                                                                             |
|               |     DataSourceExec: file_groups={3 groups: [[a.parquet], [b.parquet], [c.parquet]]}, projection=[id, arr], file_type=parquet                                                                                                      |
|               |                                                                                                                                                                                                                                  |
+---------------+----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------+
